# the principle before question 2: today sits between two payments
def _trade_chart():
    W, H = 1160, 330
    y0 = 170
    xs = {'1.3.22': 150, '1.6.22': 330, '1.9.22': 510, '1.3.23': 690, '1.9.23': 870, '...': 1010}
    p = [f'<rect x="20" y="{y0 - 2}" width="{W - 40}" height="4" rx="2" fill="#1b2d55"/><polygon points="{W - 8},{y0} {W - 24},{y0 - 8} {W - 24},{y0 + 8}" fill="#1b2d55"/>']
    for d, x in xs.items():
        if d == '...':
            p.append(T(x, y0 + 8, '···', 30, '#8a93aa', 800)); continue
        p.append(f'<circle cx="{x}" cy="{y0}" r="6" fill="#fff" stroke="#1b2d55" stroke-width="2.5"/>' + T(x, y0 + 32, d, 18, '#1b2d55', 700))
    p.append(GS(1, f'<rect class="bar" x="{xs["1.3.22"] - 26}" y="{y0 - 62}" width="52" height="54" rx="8" fill="#c9ced9"/><path d="M{xs["1.3.22"] - 14} {y0 - 48} L{xs["1.3.22"] + 14} {y0 - 22} M{xs["1.3.22"] + 14} {y0 - 48} L{xs["1.3.22"] - 14} {y0 - 22}" stroke="#e0454f" stroke-width="4" stroke-linecap="round"/>'
                + ''.join(f'<rect class="bar" x="{xs[d] - 26}" y="{y0 - 62}" width="52" height="54" rx="8" fill="#0f9d90"/>' for d in ('1.9.22', '1.3.23', '1.9.23'))
                + T(xs['1.3.23'], y0 - 72, 'התזרימים שנותרו', 18, '#0b6f66', 800), 'grow'))
    p.append(GS(1, f'<circle cx="{xs["1.6.22"]}" cy="{y0}" r="13" fill="#e8960c" stroke="#fff" stroke-width="3"/>' + T(xs['1.6.22'], y0 - 24, 'היום', 18, '#a86703', 800), 'pop', .3))
    p.append(GS(2, f'<path d="M{xs["1.9.22"] - 6} {y0 - 70} C{xs["1.9.22"] - 60} {y0 - 150}, {xs["1.3.22"] + 80} {y0 - 150}, {xs["1.3.22"] + 30} {y0 - 66}" fill="none" stroke="#ff6a4d" stroke-width="5" stroke-linecap="round" pathLength="1"/>'
                + T((xs['1.3.22'] + xs['1.9.22']) / 2, y0 - 140, 'NPV חוזר לתשלום האחרון שעבר', 18, '#c4421f', 800)
                + BADGE(xs['1.3.22'], y0 + 72, 'שווי ל-1.3.22', '#ff6a4d', fs=17), 'draw'))
    p.append(GS(3, ARW(xs['1.3.22'] + 14, y0 + 104, xs['1.6.22'] - 14, y0 + 104, '#a86703', 4, curve=18) + T((xs['1.3.22'] + xs['1.6.22']) / 2, y0 + 146, '×(1+r)^(3/12)', 19, '#a86703', 800)
                + BADGE(xs['1.6.22'] + 30, y0 + 72, 'המחיר היום', '#a86703', fs=17), 'draw'))
    return DIAG(''.join(p), W, H, 'אג״ח שנסחרת בין שני מועדי תשלום')


