# interim summary of part 3: a flowchart, revealed branch by branch
def _flow():
    W, H = 820, 360
    p = []
    p.append(GS(1, NODE(290, 6, 240, 50, '', '#1b2d55', '#1b2d55', '#fff', 18, ['איך הקרן מוחזרת?']), 'pop'))
    p.append(GS(2, ARW(470, 58, 640, 100, '#0f9d90', 3) + NODE(540, 102, 270, 62, '', '#e3f6ea', '#0f9d90', '#14532d', 16, ['בתשלום אחד, קופון קבוע', 'טבלה ו-NPV, או PV']), 'draw'))
    p.append(GS(3, ARW(350, 58, 180, 100, '#6d4df2', 3) + NODE(10, 102, 270, 62, '', '#ece8ff', '#6d4df2', '#3b2a8c', 16, ['לשיעורין, קופון משתנה', 'לוח סילוקין ו-NPV']), 'draw'))
    p.append(GS(4, ARW(675, 166, 470, 206, '#1b2d55', 2.4) + ARW(145, 166, 350, 206, '#1b2d55', 2.4) + NODE(290, 208, 240, 50, '', '#1b2d55', '#1b2d55', '#fff', 17, ['לאיזה יום מחשבים?']), 'draw'))
    leaves = [(552, '#0f9d90', '#e3f6ea', ['מיד אחרי תשלום', 'NPV מהתשלום הבא']), (282, '#6d4df2', '#ece8ff', ['רגע לפני תשלום', '×(1+r)']), (12, '#a86703', '#fff0d2', ['בין שני מועדים', '×(1+r)^(m/12)'])]
    for i, (x, st, fl, ln) in enumerate(leaves):
        p.append(GS(5, ARW(410, 260, x + 128, 290, st, 2.6) + NODE(x, 292, 256, 62, '', fl, st, '#16213a', 16, ln), 'draw', .2 * i))
    return DIAG(''.join(p), W, H, 'תרשים זרימה: בחירת כלי החישוב לפי הקרן ולפי היום')


